Invoke-Command -ComputerName srv01,srv02 { Get-Service w32time }

function Restart-ServiceSafely {
  [CmdletBinding(SupportsShouldProcess)]
  param([string]$Name, [string]$ComputerName)
  if ($PSCmdlet.ShouldProcess($ComputerName, "Restart $Name")) {
    Invoke-Command -ComputerName $ComputerName { Restart-Service $using:Name }
  }
}

Configuration WebServer {
  Node 'srv01' {
    WindowsFeature IIS { Ensure = 'Present'; Name = 'Web-Server' }
    Service W3SVC { Name = 'W3SVC'; State = 'Running' }
  }
}
